const input=$json.body??$json;
const s=v=>String(v??'').trim();
const leadId=s(input.lead_id??input.identity?.lead_id);
const propertyId=s(input.property_id??input.identity?.property_id);
const dealId=s(input.deal_id??input.identity?.deal_id);
const id=s(dealId||propertyId||leadId);
const requestId=s(input.request_id)||('evidence-reconcile:'+(id||'unknown')+':v1');
const results=Array.isArray(input.evidence_results)?input.evidence_results:[];
const byTask={};
for(const r of results){const k=s(r.task_key);if(k)byTask[k]=r;}
const required=['comps','repairs','risk','buyer_demand'];
const missing=required.filter(k=>!byTask[k]||byTask[k].ok!==true);
const successful=required.filter(k=>byTask[k]?.ok===true);
const failed=required.filter(k=>byTask[k]&&byTask[k].ok!==true);
const duplicateTasks=results.map(r=>s(r.task_key)).filter((k,i,a)=>k&&a.indexOf(k)!==i);
const conflictSignals=[];
for(const k of required){
 const r=byTask[k];
 if(r?.provider_response?.conflict===true||r?.provider_response?.status==='conflict') conflictSignals.push(k);
}
const complete=missing.length===0&&conflictSignals.length===0&&duplicateTasks.length===0;
const status=!id?'needs_context':conflictSignals.length?'evidence_conflict':missing.length?'evidence_incomplete':'evidence_complete';
const packetId='underwriting-reconciliation:'+(id||'unknown')+':v1';
return[{json:{ok:status==='evidence_complete',status,packet_id:packetId,request_id:requestId,identity:{lead_id:leadId||null,property_id:propertyId||null,deal_id:dealId||null},required_evidence:required,successful_tasks:successful,missing_tasks:missing,failed_tasks:failed,conflict_tasks:conflictSignals,duplicate_tasks:[...new Set(duplicateTasks)],completion:{complete,ready_for_aggregation:complete},routing:{next_workflow:complete?'wf-109-underwriting-evidence-aggregator':conflictSignals.length?'human_review':'wf-110-underwriting-evidence-fanout-fanin-controller',reason:complete?'all_required_evidence_reconciled':conflictSignals.length?'conflicting_evidence_requires_review':'missing_or_failed_evidence'}}}];
